      "attacks": [
        {
          "id": "okbEN7zWQ3xJAzkg",
          "name": "Jaws",
          "bonus": 20,
          "damage": "2d8 + 8 piercing",
          "traits": [
            "agile",
            "unarmed"
          ]
        }
      ],
      "actions": [
        {
          "id": "RM8HImoxZfJtj8F9",
          "name": "Tremorsense (Imprecise) 60 feet",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "Ijep1LR2jAGG5Xqz",
          "name": "Void Healing",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "ds6T4axImpnQYao4",
          "name": "Break Ground",
          "kind": "action",
          "description": "The guecubu stomps, and the ground breaks and ripples in a 30-foot emanation, erupting in razor-sharp, crisscrossing spikes of rock that deal 3d8 piercing damage to creatures in the area (check (reflex, dc:26, basic, options:area-effect) save).\nThe area becomes difficult terrain and hazardous terrain, with each square dealing 3 piercing damage to a creature that moves through it. A guecubu is immune to these effects.\nGround under the effects of a Consecrate ritual or a Circle of Protection spell tuned against evil or chaos can't be affected by this ability.",
          "traits": [
            "arcane",
            "earth"
          ]
        },
        {
          "id": "d5pg9c64JL7EqHVV",
          "name": "Earth Glide",
          "kind": "passive",
          "description": "The guecubu can Burrow through any earthen matter, including rock. When it does so, the guecubu moves at its full burrow Speed, leaving no tunnels or signs of its passing.",
          "traits": []
        },
        {
          "id": "gWdFg8nl9k3xaERt",
          "name": "Shove into Stone",
          "kind": "passive",
          "description": "When the guecubu successfully Shoves a creature into a stone barrier, the target must succeed at a check (reflex, dc:26) save or become merged with the barrier, with the effects of One with Stone until the target Escape DC 26.",
          "traits": [
            "arcane",
            "earth"
          ]
        },
        {
          "id": "d2g5vbtRBlZsAPu4",
          "name": "Wrathful Misfortune",
          "kind": "passive",
          "description": "A creature damaged by a guecubu must succeed at a check (will, dc:26) save or become cursed with consummate bad luck. The creature becomes Clumsy 2.\nEach time that creature rolls initiative, on their next roll they must roll twice and use the worse result; this is a misfortune effect.",
          "traits": [
            "arcane",
            "curse"
          ]
        }
      ],
