    "image": {
      "path": "/api/game-systems/pathfinder-2e/icons/default-icons/npc.svg"
    },
    "sourceHash": "sha256:755cad84c0c1633b21df6d55d76cce2075b5550683eaadf2b8ee036b04ef614d",
    "translatableHash": "sha256:406328d37526dc517c1aabec5784d6344ca5c82f6de1a4f78880f919c463a363",
    "data": {
      "schemaVersion": 1,
      "name": "Harmona",
      "level": 11,
      "rarity": "uncommon",
      "size": "tiny",
      "traits": [
        "chaotic",
        "fey"
      ],
      "description": "Catching a glimpse of a harmona is said to be lucky. Flying quickly, observing and scouting new areas, these brightly colored avian fey are all but hidden to the eye. A soft buzz accompanies them, discernible only to creatures with particularly keen hearing.\nIntelligent and curious, these tiny fey birds freely roam the First World, accompanying high-ranking fey creatures such as queens or their courts. In turn, companions who treat a harmona with respect for their knowledge and skill benefit from the harmona's aid in times of need.\nWhen these curious creatures find a natural gate between the planes, they glide through to explore and expand their knowledge. Those who find their way onto the Material Plane often choose to remain there in search of diverse and unusual places. This frequently leads them to the same locations that draw in curious adventurers. A harmona might befriend a non-fey adventurer as a companion, but they resent those who would treat them as pets and fight to the death to avoid capture.",
      "armorClass": 30,
      "hitPoints": 190,
      "speedFeet": 10,
      "perception": {
        "modifier": 24,
        "senses": [
          "low-light-vision"
        ]
      },
      "saves": {
        "fortitude": 18,
        "reflex": 21,
        "will": 24
      },
      "abilities": {
        "str": 0,
        "dex": 6,
        "con": 3,
        "int": 5,
        "wis": 7,
        "cha": 5
      },
      "skills": {
        "acrobatics": 23,
        "arcana": 20,
        "diplomacy": 22,
        "nature": 24,
        "performance": 22,
        "stealth": 23
      },
      "languages": [
        "fey"
      ],
      "defenses": {
        "immunities": [
          "sonic"
        ],
        "resistances": [],
        "weaknesses": [
          "cold-iron 10"
        ]
      },
      "attacks": [
        {
          "id": "rVdhm2xzR2AUjY4g",
          "name": "Beak",
          "bonus": 23,
          "damage": "2d6 + 6 piercing; 2d6 sonic",
          "traits": [
            "finesse",
            "magical",
            "unarmed"
          ]
        },
        {
          "id": "wY1dx0xYE5qgM9aA",
          "name": "Sonic Pulse",
          "bonus": 23,
          "damage": "2d12 + 6 sonic",
          "traits": [
            "magical",
            "sonic"
          ]
        }
      ],
      "actions": [
        {
          "id": "n8MOp28YVOpx7Eoq",
          "name": "Flit Back",
          "kind": "reaction",
          "description": "Trigger A creature enters the harmona's space or an adjacent square\nEffect The harmona Flies 10 feet away from the triggering creature.",
          "traits": []
        },
        {
          "id": "UuZpaLnXCCuS5ijA",
          "name": "Concussive Blow",
          "kind": "action",
          "description": "The harmona makes a beak Strike, channeling disruptive sound waves into the blow. On a hit, the target must succeed at a check (fortitude, dc:30) save or become Stunned 1 (Stunned 2 on a critical failure).\nAfter this Strike, the harmona can Fly up to half their fly Speed.",
          "traits": [
            "primal",
            "sonic"
          ]
        },
        {
          "id": "znaX5hWmLXH23ywJ",
          "name": "Subsonic Pulse",
          "kind": "action",
          "description": "The harmona beats their wings rapidly towards the ground, creating a nearly inaudible rumble and sending a wave of shaking earth to overwhelm their enemies.\nEach creature in a 15-foot emanation must succeed at a check (fortitude, dc:30, basic, options:area-effect,inflicts:prone) save or take 6d6 sonic damage. A creature that fails its save is knocked Prone from the shaking ground.",
          "traits": [
            "primal"
          ]
        },
        {
          "id": "9iPQQuORbP2KlVOO",
          "name": "Ultrasonic Thrust",
          "kind": "action",
          "description": "The harmona beats their wings skyward, creating a spiraling vibration. Each creature in a 30-foot cone must attempt a check (reflex, dc:30, options:area-effect,damaging-effect,forced-movement,inflicts:off-guard,inflicts:prone) save as the high-frequency blast flings them up and away.\nCritical Success The creature is unaffected.\nSuccess The creature is pushed 5 feet away and knocked off balance, becoming Off-Guard until the start of their next turn.\nFailure Sonic waves fling the creature 15 feet back from the harmona. The creature takes 6d6 bludgeoning damage from the fall and lands Prone.\nCritical Failure As failure, but the creature is flung 30 feet and takes double damage.",
          "traits": [
            "primal",
            "sonic"
          ]
        },
        {
          "id": "LVNb1MU1A4uFDYSo",
          "name": "Push",
          "kind": "action",
          "description": "",
          "traits": []
        }
      ],
      "spellcasting": [
        {
          "id": "hPBPkTGmnJVgZ22X",
          "name": "Primal Innate Spells",
          "tradition": "primal",
          "category": "innate",
          "attackModifier": 22,
          "saveDc": 30,
          "spells": [
            {
              "id": "4WBGK49Rnd36v5dN",
              "name": "Detect Magic",
              "rank": 1
            }
          ]
        }
      ]
    }
