        {
          "id": "92aGlrWvxAQQzu5H",
          "name": "Cheaters Never Prosper",
          "kind": "passive",
          "description": "50 feet. A creature within the aura who uses or benefits from an effect with the fortune trait must succeed at a check (will, dc:34, options:inflicts:slowed) save or become Slowed 1 for 1 round (Slowed 2 on a critical failure).",
          "traits": [
            "aura",
            "occult"
          ]
        },
        {
          "id": "hKMqAgh48onTAhpH",
          "name": "Clinch Victory",
          "kind": "reaction",
          "description": "Trigger A creature within the triumph siktempora's reach uses an action that would restore Hit Points\nEffect The triumph siktempora makes a glorious fist Strike against the triggering creature. On a critical success, this Strike also disrupts the triggering action.",
          "traits": []
        },
        {
          "id": "O36hrH8CJRLhvwrI",
          "name": "Temporal Sense",
          "kind": "passive",
          "description": "A siktempora can always roll Dimension of Time Lore for initiative. When it does, it gains a +2 circumstance bonus to the roll.",
          "traits": []
        },
        {
          "id": "CZTZt5TtBNcJtjOp",
          "name": "Uncanny Pounce",
          "kind": "passive",
          "description": "Trigger The triumph siktempora rolls Dimension of Time Lore for initiative\nEffect The triumph siktempora Strides once and makes a claw Strike, in either order.",
          "traits": []
        },
        {
          "id": "xsnc3cQ3J9m1QSHk",
          "name": "Vie for Victory",
          "kind": "action",
          "description": "The triumph siktempora pushes themself beyond their limits to secure victory over a chosen foe. They choose one target they can see and reach with a single Stride action. They attempt to Demoralize that target, ignoring the typical limitations on distance and with no penalty for not sharing a language with the target. They then Stride and attempt one Athletics attack action (such as Grapple or Disarm) against the target.",
          "traits": []
        },
        {
          "id": "dRWLZGZySawLWgLz",
          "name": "Winning Smile",
          "kind": "action",
          "description": "The triumph siktempora flashes their disarming grin at one creature within 15 feet. The target takes 10d8 mental damage (check (will, dc:34, basic) save). On a failure, the target's attacks against the triumph siktempora also become nonlethal until the end of the target's next turn.\nEffect: Winning Smile",
          "traits": [
            "emotion",
            "mental",
            "occult"
          ]
        }
