        {
          "id": "f3HhM7YpmtEJwP4y",
          "name": "Void Healing",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "v1cjchmhqo6lvdjy",
          "name": "Coordinated Strike",
          "kind": "passive",
          "description": "The wight commander flanks with an ally as long as the target is within both their reaches, even if commander and ally aren't on opposite sides.",
          "traits": []
        },
        {
          "id": "ombjfkyxjmwbb9xc",
          "name": "Drain Life",
          "kind": "passive",
          "description": "When the hunter wight damages a living creature using an unarmed attack or their bound weapon, they gain 12 temporary Hit Points, and the creature must succeed at a check (fortitude, dc:29, options:inflicts:drained) save or become Drained 1. Further damage dealt by the hunter wight's unarmed and bound weapon attacks increases the value of the drained condition by 1 on a failed save, to a maximum of drained 4.\nEffect: Drain Life",
          "traits": [
            "divine"
          ]
        },
        {
          "id": "581dy5lnt449p866",
          "name": "Spawn Wight Soldier",
          "kind": "passive",
          "description": "A living humanoid killed by a wight commander's weapon or claw Strike rises as a wight of the commander's level or lower, most often a hunter wight or prowler wight, after 1d4. This spawn is under the command of the wight commander that killed them. They don't have drain life or spawn wight soldier and are Clumsy 2 for as long as they're a wight spawn. If the creator of the wight spawn dies, the wight spawn becomes a fully autonomous wight; they regain their free will, gain drain life and spawn wight soldier, and are no longer clumsy.",
          "traits": [
            "divine"
          ]
        },
        {
          "id": "9uwteydd6ypzaa2e",
          "name": "Tactical Direction",
          "kind": "action",
          "description": "Each wight ally in a 30-foot emanation gains the Attack of Opportunity reaction until the end of their next turn.",
          "traits": [
            "auditory"
          ]
        }
