    "translatableHash": "sha256:667889c50a308f05098817bd019b398bad4dcc92da7c42235751ce678b7d1ee2",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Glimpse Grave",
      "level": 20,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "haunt"
      ],
      "description": "A tombstone bears the name of those who look upon it, causing their hearts to seize.",
      "armorClass": 10,
      "hitPoints": 10,
      "hardness": 0,
      "stealth": {
        "modifier": 38,
        "details": "(expert) to notice the words on the tombstone waver"
      },
      "disable": "check (religion, dc:45, name:Bless the tombstone) (legendary) to bless the tombstone or check (occultism, dc:50, name:Ward off the spirits) (trained) to ward off spirits",
      "isComplex": false,
      "routine": "",
      "reset": "1 day",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "ShZ2CAIzf05F41B2",
          "name": "Stop Heart",
          "kind": "reaction",
          "description": "Trigger A creature reads or touches the tombstone\nEffect The haunt deals 8d10+44 void damage (check (will, dc:47, basic)) to all creatures within 60-foot emanation who can see the tombstone and can read any language. On a critical failure, a creature dies.",
          "traits": [
            "death",
            "illusion",
            "incapacitation",
            "linguistic",
            "occult",
            "visual"
          ]
        }
      ]
    }
