    "sourceHash": "sha256:4c0a3c1ad35eacae2eec723d7ed400ebe0c9d72e93f26a075f93f5fd691c9c3e",
    "translatableHash": "sha256:4a02fc6115fc3fdcd1d5865fbb41e0a57cf8d6ddd088983f1385ead5bfba3e08",
    "data": {
      "schemaVersion": 1,
      "name": "Somnalu",
      "level": 15,
      "rarity": "unique",
      "size": "huge",
      "traits": [
        "aberration",
        "dream",
        "evil"
      ],
      "description": "With its lithe, sinuous body and a flexible, twisting spine, Somnalu bears a resemblance to a giant lizard, save for its striking visage. Spiny frills run down the creature's mottled black back, interlaced with dull red stripes that streak from head to tail. Its two sets of forelimbs are bound to each other by small webs of skin. Its distinctive face lacks any visible mouth, nose, or ears, instead possessing only a huge red eye surrounded by six smaller, secondary eyes.",
      "armorClass": 37,
      "hitPoints": 290,
      "speedFeet": 30,
      "perception": {
        "modifier": 29,
        "senses": [
          "greater-darkvision",
          "scent-imprecise-60"
        ]
      },
      "saves": {
        "fortitude": 25,
        "reflex": 25,
        "will": 29
      },
      "abilities": {
        "str": 9,
        "dex": 6,
        "con": 6,
        "int": 8,
        "wis": 8,
        "cha": 4
      },
      "skills": {
        "arcana": 27,
        "athletics": 27,
        "occultism": 30,
        "survival": 25
      },
      "languages": [
        "aklo"
      ],
      "defenses": {
        "immunities": [
          "acid"
        ],
        "resistances": [
          "mental 10",
          "poison 15"
        ],
        "weaknesses": [
          "cold 15"
        ]
      },
      "attacks": [
        {
          "id": "u7kd3tksjclaxe9p",
          "name": "Claw",
          "bonus": 30,
          "damage": "3d12+17 slashing",
          "traits": [
            "reach-10",
            "unarmed"
          ]
        },
        {
          "id": "2851cqyevsdj0pv1",
          "name": "Tail Barbs",
          "bonus": 30,
          "damage": "3d8+17 piercing",
          "traits": [
            "agile",
            "reach-20"
          ]
        }
      ],
      "actions": [
        {
          "id": "GJfVPSI8F9jNbRlK",
          "name": "Greater Darkvision",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "g4ycspvuloiaj0dg",
          "name": "Baleful Gaze",
          "kind": "reaction",
          "description": "Trigger A creature within 100 feet makes a ranged attack or uses an action that has the concentrate trait\nEffect Somnalu fixes its central eye upon the triggering creature in an attempt to frighten it, jolting it and disrupting its action. The creature must attempt a check (will, dc:36) save; on a failure, Somnalu disrupts the triggering action and the creature is Frightened 1.",
          "traits": []
        },
        {
          "id": "3c3e525945gksbuz",
          "name": "Corrosive Wounds",
          "kind": "passive",
          "description": "The acid that coats the skin of Somnalu eats away at a weapon that Strikes it. As long as Digestive Secretions is active on Somnalu, whenever a creature hits Somnalu with a metal or wooden weapon, the creature must succeed at a check (reflex, dc:33, traits:damaging-effect) save or else the weapon takes 2d8 acid damage (after dealing damage to Somnalu as normal). Thrown weapons and ammunition take this damage automatically with no saving throw.",
          "traits": []
        },
        {
          "id": "glcioqtbc3vb4ph9",
          "name": "Frightful Presence",
          "kind": "passive",
          "description": "30 feet. check (will, dc:33, options:area-effect,inflicts:frightened)",
          "traits": [
            "aura",
            "emotion",
            "fear",
            "mental"
          ]
        },
        {
          "id": "xj5rnq18yhd2zsa2",
          "name": "Sleep Scent (Imprecise) 60 feet",
          "kind": "passive",
          "description": "Somnalu can smell creatures that are asleep, as the scent ability.",
          "traits": []
        },
        {
          "id": "kydqwskabqnx5uq7",
          "name": "Acid Spew",
          "kind": "action",
          "description": "Somnalu jets acid from its skin, dousing all creatures in a 60-foot line. Each creature in this area takes 10d8 acid damage (check (reflex, dc:33, basic, options:area-effect) save). It can't use this ability again for 1d4.",
          "traits": []
        },
        {
          "id": "3jj4b4xi38vnp8ff",
          "name": "Caustic Trench",
          "kind": "action",
          "description": "Somnalu Burrows three times. It digs a trench along its path, filling the trench with acid pumped from its skin. The trench is hazardous terrain, and any creature that moves into it takes 4d6 persistent acid damage. While Burrowing, if Somnalu would move through a space occupied by another creature, that creature must attempt a check (reflex, dc:36) save to avoid falling into the trench and taking the acid damage. The acid remains for 1 minute.",
          "traits": []
        },
        {
          "id": "5ferfswsjapb1v73",
          "name": "Digestive Secretions",
          "kind": "action",
          "description": "Somnalu secretes acid for 1 round. Whenever it makes a melee Strike, it deals an additional 2d8 splash)[acid damage]. Like most splash damage, this damage applies to the target and adjacent creatures and applies even on a failure, though not on a critical failure.",
          "traits": []
        },
        {
          "id": "5r9xpx4m7n8g0n3t",
          "name": "Drain Nutrients",
          "kind": "action",
          "description": "Somnalu targets a creature with a claw Strike. On a success, Somnalu drains the creature's life through its skin. The creature must succeed at a check (fortitude, dc:36) save or become Drained 2 (Drained 1 on a success, no effect on a critical success). Somnalu gains temporary Hit Points equal to the amount of Hit Points the creature loses from this Strike.",
          "traits": []
        },
        {
          "id": "gy8tszy8y7642gmz",
          "name": "Vent Fumes",
          "kind": "action",
          "description": "Somnalu blasts poison gas in a 30-foot burst. The gas lingers for 1 round, and all creatures that begin their turn in the gas or enter the gas take 4d8 poison damage (check (fortitude, dc:36, basic, options:area-effect) save). Any creature in the gas is Concealed, and other creatures are concealed to all creatures in the gas. However, Somnalu can see through this concealment.",
          "traits": []
        },
        {
          "id": "aGTy9BdANkUxx360",
          "name": "Improved Grab",
          "kind": "passive",
          "description": "",
          "traits": []
        }
      ],
      "spellcasting": [
        {
          "id": "BhXjGUlWmAeZnxYg",
          "name": "Occult Innate Spells",
          "tradition": "occult",
          "category": "innate",
          "attackModifier": 0,
          "saveDc": 36,
          "spells": [
            {
              "id": "SK5P9sETDNPurvYY",
              "name": "Darkness (At Will)",
              "rank": 4
            },
            {
              "id": "8IyvaCeWH0G9ku5Z",
              "name": "Silence (At Will)",
              "rank": 4
            },
            {
              "id": "H3nTHf2tY5FRLurY",
              "name": "Sleep (At Will)",
              "rank": 4
            },
            {
              "id": "MJYJBo8c9AViW0Jo",
              "name": "Strange Geometry",
              "rank": 5
            },
            {
              "id": "xIqz5Bh9c7F4tSmr",
              "name": "Lure Dream",
              "rank": 6
            },
            {
              "id": "nA9FpxXDu7w1IpSw",
              "name": "Vibrant Pattern",
              "rank": 6
            },
            {
              "id": "GEu7Rgt392YD5DKv",
              "name": "Hypnopompic Terrors",
              "rank": 8
            }
          ]
        }
      ]
    }
