        {
          "id": "Thxxg6IpvoOEOFZu",
          "name": "Scoff at the Divine",
          "kind": "reaction",
          "description": "Trigger A creature within 30 feet casts a divine spell or uses a divine ability.\nRequirements Vaklish has an unexpended spell slot that can be used to cast Dispel Magic.\nEffect Vaklish expends a spell slot that could be used to cast dispel magic and attempts to counteract the triggering spell or ability.\nVaklish can't Scoff at the Divine for 1d4.",
          "traits": []
        },
        {
          "id": "QFVHYWU00lctwBwf",
          "name": "Change Shape",
          "kind": "action",
          "description": "Vaklish takes on the appearance of any Medium humanoid. This doesn't change Valish's Speed or the attack and damage modifiers with his Strikes but might change the damage type his Strikes deal (typically to bludgeoning). He typically loses his fangs Strike unless the humanoid form has fangs or a similar unarmed attack.",
          "traits": [
            "concentrate",
            "occult",
            "polymorph"
          ]
        },
        {
          "id": "yqO9SHE3AFcvwy0R",
          "name": "Disturbing Vision",
          "kind": "action",
          "description": "Vaklish's eyes flash green as it projects a telepathic wave in a 30-foot emanation. All creatures in the area are assailed by a vision of evil decadence from one of the rakshasa's past lives. Each non-evil creature in the area must succeed at a check (will, dc:32) save or become Sickened 1 (and Stunned 1 on a critical failure).\nThe visions last 1d4, and while they do, Vaklish and all evil creatures in the area gain a +1 status bonus to all checks. Vaklish can use this ability again only once the previous visions end.\nEffect: Disturbing Vision",
          "traits": [
            "concentrate",
            "mental",
            "occult"
          ]
        }
